const r = $input.first().json;
const steps = Array.isArray(r.intermediateSteps) ? r.intermediateSteps : [];
const clean = v => String(v ?? '').replace(/<[^>]*>/g, '').replace(/@(here|channel|everyone)\b/gi, '$1');
const registros = steps.map((s, i) => {
  const raw = s.observation;
  let o = raw;
  if (typeof o === 'string') { try { o = JSON.parse(o); } catch {} }
  const rows = Array.isArray(o) ? o : [o];
  const failed = rows.some(x => x && typeof x === 'object' && (x.error || x.success === false));
  const confirmed = !failed && rows.some(x => {
    const row = x?.json ?? x;
    return row && typeof row === 'object' && String(row.ticket_id ?? '') === String($execution.id);
  });
  return { numero: i + 1, herramienta: clean(s.action?.tool || 'no identificada'),
    resultado: failed ? 'error devuelto por herramienta' : confirmed ? 'herramienta devolvió registro con ticket_id de esta ejecución' : 'resultado no confirmado; revisar ejecución en n8n' };
});
const respuesta = r.error ? 'El agente falló. Se requiere revisión humana; no se confirma el registro.' : clean(r.output || 'El agente no devolvió una respuesta final.');
const detalle = registros.length ? registros.map(x => x.numero + '. ' + x.herramienta + ': ' + x.resultado).join('\n') : 'Sin llamadas observables a herramientas. Verificar si el mensaje requería un ticket.';
return [{json: {output: respuesta, texto_slack: ('SUPERVISIÓN DE SOPORTE\nEjecución: ' + $execution.id + '\n\nRESPUESTA PROPUESTA\n' + respuesta + '\n\nREGISTRO DE HERRAMIENTAS\n' + detalle + '\n\nLímite del agente: 5 iteraciones. La prioridad y el equipo son una propuesta para revisión humana.').slice(0,12000), llamadas: registros.length}}];
